import { test } from 'node:test';
import assert from 'node:assert/strict';
import { lerArquivoFake } from './solution.mjs';

// Função fake de leitura: simula o fs.promises.readFile (sem arquivo real).
const leitorFake = (nome) => {
  const arquivos = {
    'notas.txt': 'comprar leite\ncomprar pão\n',
    'diario.txt': '  hoje foi um bom dia  ',
  };
  return Promise.resolve(arquivos[nome] ?? '');
};

test('lê um arquivo fake e devolve o conteúdo sem espaços extras', async () => {
  const conteudo = await lerArquivoFake(leitorFake, 'diario.txt');
  assert.equal(conteudo, 'hoje foi um bom dia');
});

test('lê outro arquivo fake e devolve o conteúdo com as quebras de linha', async () => {
  const conteudo = await lerArquivoFake(leitorFake, 'notas.txt');
  assert.equal(conteudo, 'comprar leite\ncomprar pão');
});

test('rejeita quando o nome do arquivo é vazio', async () => {
  await assert.rejects(() => lerArquivoFake(leitorFake, ''), /inválido/);
});

test('propaga o erro quando a leitura falha', async () => {
  const leitorQueFalha = () => Promise.reject(new Error('arquivo não encontrado'));
  await assert.rejects(() => lerArquivoFake(leitorQueFalha, 'x.txt'), /não encontrado/);
});

solutionCode:
export async function lerArquivoFake(ler, nomeArquivo) {
  if (typeof nomeArquivo !== 'string' || nomeArquivo.trim() === '') {
    throw new Error('nome de arquivo inválido');
  }
  const conteudo = await ler(nomeArquivo);
  return conteudo.trim();
}
